import { NextResponse } from 'next/server';
import { exec } from 'child_process';
import { promises as fs } from 'fs';
import path from 'path';

const execAsync = (command: string) => {
  return new Promise<{ stdout: string; stderr: string }>((resolve, reject) => {
    exec(command, (error, stdout, stderr) => {
      if (error) {
        reject({ error, stdout, stderr });
      } else {
        resolve({ stdout, stderr });
      }
    });
  });
};

export async function GET() {
  const results: any = {};

  try {
    // Gateway status
    try {
      const { stdout } = await execAsync('openclaw gateway status');
      results.gatewayStatus = stdout.trim();
    } catch (e: any) {
      results.gatewayStatus = `Error: ${e.message}`;
    }

    // Sessions directory
    const sessionsDir = path.join(process.env.LOCALAPPDATA ?? '', 'openclaw', 'sessions');
    try {
      const files = await fs.readdir(sessionsDir);
      results.sessions = {
        count: files.length,
        files: files.slice(0, 10), // limit to 10
      };
    } catch (e) {
      results.sessions = { error: 'Failed to read sessions directory', details: (e as Error).message };
    }

    // Wrapper script
    const wrapperPath = path.join(process.env.USERPROFILE ?? '', 'Warlord_Inc', 'Warlord_WASP', 'OpenClaw', 'run-agent.ps1');
    try {
      await fs.access(wrapperPath);
      results.wrapperExists = true;
      results.wrapperPath = wrapperPath;
    } catch (e) {
      results.wrapperExists = false;
      results.wrapperPath = wrapperPath;
    }

    // Recent logs
    const logDir = path.join(process.env.LOCALAPPDATA ?? '', 'Temp', 'openclaw');
    try {
      const files = await fs.readdir(logDir);
      const logFiles = files.filter(f => f.startsWith('openclaw-') && f.endsWith('.log'));
      if (logFiles.length === 0) {
        results.recentLogs = ['No log files found'];
      } else {
        // Sort by date descending (assuming format openclaw-YYYY-MM-DD.log)
        const sorted = logFiles.sort().reverse();
        const latestLog = path.join(logDir, sorted[0]);
        const logData = await fs.readFile(latestLog, 'utf8');
        const lines = logData.split('\n').slice(-10); // last 10 lines
        results.recentLogs = lines;
      }
    } catch (e) {
      results.recentLogs = [`Error reading logs: ${(e as Error).message}`];
    }

    return NextResponse.json(results);
  } catch (e) {
    return NextResponse.json({ error: 'Internal server error', details: (e as Error).message }, { status: 500 });
  }
}

