'use client';

import React, { useEffect, useState } from 'react';

type TokenData = {
  tier3: Array<{
    agent: string;
    model: string;
    tokensUsed: number;
    lastUpdated: string;
    allocation: {
      monthly: number;
      used: number;
      remaining: number;
    };
  }>;
  tier2: Array<{
    agent: string;
    model: string;
    tokensUsed: number;
    lastUpdated: string;
    allocation: {
      monthly: number;
      used: number;
      remaining: number;
    };
  }>;
  tier1: Array<{
    agent: string;
    model: string;
    tokensUsed: number;
    lastUpdated: string;
    allocation: {
      monthly: number;
      used: number;
      remaining: number;
      note?: string;
    };
  }>;
  summary: {
    totalTokens: {
      tier3: number;
      tier2: number;
      tier1: number;
    };
    alerts: Array<{
      type: 'info' | 'warning' | 'error';
      msg: string;
    }>;
  };
};

export default function TokenMonitoringDashboard() {
  const [tokenData, setTokenData] = useState<TokenData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const response = await fetch('/api/token-monitor');
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setTokenData(data);
        setError(null);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Unknown error');
        setTokenData(null);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
    // Refresh every 30 seconds
    const interval = setInterval(fetchData, 30000);
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return (
      <div className="p-6">
        <div className="text-center py-12">
          <div className="animate-spin rounded-full border-[3px] border-b-rhythm-goldenrod-core w-12 h-12 mx-auto mb-4"></div>
          <p className="text-rhythm-silver-mist">Loading token monitoring data...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6">
        <div className="bg-rhythm-marbon-depth/20 border border-rhythm-slate-reflection/20 rounded-sm p-4">
          <p className="text-rhythm-signal-fault">Error: {error}</p>
        </div>
      </div>
    );
  }

  if (!tokenData) {
    return (
      <div className="p-6">
        <div className="text-center py-12">
          <p className="text-rhythm-silver-mist">No data available</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-rhythm-goldenrod-core">
          Token Monitoring & LLM Governance Dashboard
        </h2>
        <div className="text-rhythm-silver-mist text-sm">
          Last updated: {new Date(tokenData.tier3[0]?.lastUpdated || Date.now()).toLocaleTimeString()}
        </div>
      </div>

      {/* Summary Alerts */}
      {tokenData.summary.alerts.map((alert, idx) => (
        <div key={idx} className={`p-3 rounded border border-[rgba(148,163,184,0.1)] bg-[rgba(10,10,15,0.6)]`}>
          <span className={`text-xs font-medium ${alert.type === 'info' ? 'text-signal-active' : alert.type === 'warning' ? 'text-signal-fault' : 'text-silver-mist'}`}>
            {alert.msg}
          </span>
        </div>
      ))}

      {/* Tier 3: Elite Frontier Gate */}
      <div className="bg-rhythm-charcoal-matte border border-rhythm-slate-reflection/30 rounded-sm p-4">
        <div className="mb-4">
          <h3 className="text-lg font-semibold text-rhythm-goldenrod-core">
            Tier 3: Elite Frontier Gate (Claude 3.5 Sonnet via OpenRouter)
          </h3>
          <p className="text-rhythm-silver-mist text-xs mt-1">
            Strictly Restricted / Pay-Per-Token Billing. Authorized Agent: Skylar exclusively.
          </p>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-rhythm-silver-mist">
            <thead className="border-b border-rhythm-slate-reflection/20">
              <tr>
                <th className="text-left p-2">Agent</th>
                <th className="text-left p-2">Model</th>
                <th className="text-center p-2">Tokens Used</th>
                <th className="text-center p-2">Monthly Allocation</th>
                <th className="text-center p-2">Remaining</th>
                <th className="text-center p-2">Last Updated</th>
              </tr>
            </thead>
            <tbody>
              {tokenData.tier3.map((item, idx) => (
                <tr key={idx} className="border-t border-rhythm-slate-reflection/10">
                  <td className="p-2 font-mono">{item.agent}</td>
                  <td className="p-2 font-mono">{item.model}</td>
                  <td className="p-2 font-mono text-rhythm-goldenrod-core">{item.tokensUsed.toLocaleString()}</td>
                  <td className="p-2 font-mono">
                    {item.allocation.monthly.toLocaleString()}
